//! 🫴️ Domain-neutral paid SQL destinations and indexes borrow the original native receiving wallet.
use super::super::{SqliteDatabase,SqliteRow,SqliteValue,SqliteSnapshotControl,SqliteSnapshotPhase};
use semio_framework_value::{ValueError,ValueRefusalKind,NativeDecodeControl,NativeEncodeControl,RetainedCloneGrant,RetainedCloneProgress};
use std::{cmp::Ordering,mem::size_of};
type Result<T>=std::result::Result<T,ValueError>;
fn error(kind:ValueRefusalKind,message:&'static str)->ValueError{ValueError::literal(kind,message)}
fn invalid(message:&'static str)->ValueError{error(ValueRefusalKind::InvalidValue,message)}
/// 🎟️ Runs paid destination operations through an existing original wallet without creating authority.
pub trait ReceivingWallet{
 fn admit_frontier(&self,demand:RetainedCloneGrant)->Result<()>;
 fn record_progress(&mut self,progress:RetainedCloneProgress)->Result<()>;
 fn allocate_vec_into<T>(&mut self,native:&mut NativeDecodeControl<'_>,count:usize,output:&mut Vec<T>,depth:usize)->Result<()>;
 fn allocate_encode_vec_into<T>(&mut self,native:&mut NativeEncodeControl<'_>,count:usize,output:&mut Vec<T>,depth:usize)->Result<()>;
 fn copy_text_into(&mut self,native:&mut NativeDecodeControl<'_>,text:&str,output:&mut String,depth:usize)->Result<()>;
 fn copy_encode_text_into(&mut self,native:&mut NativeEncodeControl<'_>,text:&str,output:&mut String,depth:usize)->Result<()>;
}
/// 🔢️ Converts an authored ordinal without unsigned truncation.
pub fn ordinal(value:usize)->Result<i64>{i64::try_from(value).map_err(|_|error(ValueRefusalKind::WorkLimit,"SQLite ordinal exceeds signed extent"))}
/// 🧱️ Reads a declared scalar without owning diagnostic strings.
pub fn integer(row:&SqliteRow,column:usize)->Result<i64>{match row.values.get(column){Some(SqliteValue::Integer(value))=>Ok(*value),_=>Err(invalid("SQLite integer cell is invalid"))}}
pub enum Direction<'a,'b>{Decode(&'a mut NativeDecodeControl<'b>),Encode(&'a mut NativeEncodeControl<'b>)}
pub struct Port<'a,'b,'c,B:ReceivingWallet>{pub control:&'a mut SqliteSnapshotControl<'b>,pub native:Direction<'a,'c>,pub body:&'a mut B}
impl<B:ReceivingWallet> Port<'_,'_,'_,B>{
 pub fn phase(&self)->SqliteSnapshotPhase{match &self.native{Direction::Decode(_)=>SqliteSnapshotPhase::ProjectSnapshot,Direction::Encode(_)=>SqliteSnapshotPhase::ReconstructSnapshot}}
 pub fn owned(&self)->usize{match &self.native{Direction::Decode(native)=>native.owned_bytes(),Direction::Encode(native)=>native.owned_bytes()}}
 pub fn receipt(&mut self,before:usize)->Result<()>{let actual=self.owned().checked_sub(before).ok_or_else(||error(ValueRefusalKind::InvariantViolated,"SQLite original allocation receipt regressed"))?;self.control.admit_native_allocation_bytes(actual)}
 pub fn admit(&self,bytes:usize)->Result<()>{if bytes>self.control.allocation_remaining_bytes(){return Err(error(ValueRefusalKind::OwnershipLimit,"SQLite receiving backing exceeds original SQL allowance"))}Ok(())}
 pub fn work(&mut self,depth:usize,copy:usize)->Result<()>{let phase=self.phase();self.control.checkpoint(phase,0,0)?;match &mut self.native{Direction::Decode(native)=>native.checkpoint()?,Direction::Encode(native)=>native.checkpoint()?}self.body.admit_frontier(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:depth})?;self.body.record_progress(RetainedCloneProgress{copied_items:1,copied_bytes:copy,..Default::default()})}
 pub fn vector<T>(&mut self,count:usize,output:&mut Vec<T>,depth:usize)->Result<()>{let bytes=count.checked_mul(size_of::<T>()).filter(|bytes|*bytes<=isize::MAX as usize).ok_or_else(||error(ValueRefusalKind::OwnershipLimit,"SQLite receiving vector extent overflow"))?;self.admit(bytes)?;let phase=self.phase();self.control.checkpoint(phase,0,count)?;let before=self.owned();let result=match &mut self.native{Direction::Decode(native)=>self.body.allocate_vec_into(native,count,output,depth),Direction::Encode(native)=>self.body.allocate_encode_vec_into(native,count,output,depth)};self.receipt(before)?;result}
 pub fn text(&mut self,text:&str,output:&mut String,depth:usize)->Result<()>{self.admit(text.len())?;let phase=self.phase();self.control.checkpoint(phase,0,text.len())?;let before=self.owned();let control=&mut *self.control;let body=&mut *self.body;let result=match &mut self.native{Direction::Decode(native)=>{let mut observe=|event:semio_framework_value::native_decoding::NativeDecodeProgress|control.observe_progress(phase,event.completed,event.total);native.scoped_observer(&mut observe,|native|body.copy_text_into(native,text,output,depth))},Direction::Encode(native)=>{let mut observe=|event:semio_framework_value::native_encoding::NativeEncodeProgress|control.observe_progress(phase,event.completed,event.total);native.scoped_observer(&mut observe,|native|body.copy_encode_text_into(native,text,output,depth))}};self.receipt(before)?;result}
}
/// 🫴️ Moves an original collection through two retained fields without dropping refused growth.
pub fn relocate_vector<T,B:ReceivingWallet>(original:&mut Vec<T>,replacement:&mut Vec<T>,capacity:usize,depth:usize,port:&mut Port<'_,'_,'_,B>)->Result<()>{
 if capacity<original.len(){return Err(error(ValueRefusalKind::OwnershipLimit,"SQLite replacement cannot retain its original elements"))}port.vector(capacity,replacement,depth)?;while !original.is_empty(){port.work(depth,size_of::<T>())?;replacement.push(original.pop().unwrap());}let count=replacement.len();for index in 0..count/2{port.work(depth,2*size_of::<T>())?;replacement.swap(index,count-1-index);}port.work(depth,3*size_of::<Vec<T>>())?;std::mem::swap(original,replacement);Ok(())
}
#[derive(semio_framework_value::RetireOwned)]
pub struct Projection{pub database:SqliteDatabase,pub row:SqliteRow,pub value_bytes:usize}
impl Projection{pub fn new()->Self{Self{database:SqliteDatabase{tables:Vec::new()},row:SqliteRow{rowid:0,values:Vec::new()},value_bytes:0}}}
/// 🪙️ A borrowed projection scalar has no owned backing to lose before admission.
#[derive(Clone,Copy)]
pub enum Scalar{Null,Integer(i64),Real(f64)}
pub fn cell<B:ReceivingWallet>(frame:&mut Projection,value:Scalar,port:&mut Port<'_,'_,'_,B>)->Result<()>{let bytes=match value{Scalar::Null=>0,_=>8};frame.value_bytes=frame.value_bytes.checked_add(bytes).ok_or_else(||error(ValueRefusalKind::OwnershipLimit,"SQLite value extent overflow"))?;port.control.check_value_bytes(frame.value_bytes)?;port.work(4,size_of::<SqliteValue>())?;frame.row.values.push(match value{Scalar::Null=>SqliteValue::Null,Scalar::Integer(value)=>SqliteValue::Integer(value),Scalar::Real(value)=>SqliteValue::Real(value)});Ok(())}
pub fn text_cell<B:ReceivingWallet>(frame:&mut Projection,text:&str,port:&mut Port<'_,'_,'_,B>)->Result<()>{frame.value_bytes=frame.value_bytes.checked_add(text.len()).ok_or_else(||error(ValueRefusalKind::OwnershipLimit,"SQLite value extent overflow"))?;port.control.check_value_bytes(frame.value_bytes)?;port.work(4,size_of::<SqliteValue>())?;frame.row.values.push(SqliteValue::Text(String::new()));let Some(SqliteValue::Text(output))=frame.row.values.last_mut()else{unreachable!()};port.text(text,output,4)}
pub fn row<B:ReceivingWallet>(frame:&mut Projection,id:i64,width:usize,port:&mut Port<'_,'_,'_,B>)->Result<()>{port.vector(width,&mut frame.row.values,3)?;frame.row.rowid=id;cell(frame,Scalar::Integer(id),port)}
pub fn push_row<B:ReceivingWallet>(frame:&mut Projection,table:usize,port:&mut Port<'_,'_,'_,B>)->Result<()>{port.work(3,size_of::<SqliteRow>())?;frame.database.tables[table].rows.push(std::mem::replace(&mut frame.row,SqliteRow{rowid:0,values:Vec::new()}));Ok(())}
pub fn sort<B:ReceivingWallet>(indices:&mut[usize],port:&mut Port<'_,'_,'_,B>,mut compare:impl FnMut(usize,usize)->Result<Ordering>)->Result<()>{fn sift<B:ReceivingWallet>(indices:&mut[usize],mut root:usize,end:usize,port:&mut Port<'_,'_,'_,B>,compare:&mut impl FnMut(usize,usize)->Result<Ordering>)->Result<()>{while root<end/2{port.work(1,0)?;let mut child=root*2+1;if child+1<end&&compare(indices[child],indices[child+1])?.is_lt(){child+=1}if !compare(indices[root],indices[child])?.is_lt(){break}port.work(1,2*size_of::<usize>())?;indices.swap(root,child);root=child;}Ok(())}for root in(0..indices.len()/2).rev(){sift(indices,root,indices.len(),port,&mut compare)?}for end in(1..indices.len()).rev(){port.work(1,2*size_of::<usize>())?;indices.swap(0,end);sift(indices,0,end,port,&mut compare)?}Ok(())}
pub fn identity_position<B:ReceivingWallet>(rows:&[SqliteRow],ids:&[usize],identity:i64,port:&mut Port<'_,'_,'_,B>)->Result<Option<usize>>{let(mut low,mut high)=(0,ids.len());while low<high{port.work(1,0)?;let middle=low+(high-low)/2;match rows[ids[middle]].rowid.cmp(&identity){Ordering::Less=>low=middle+1,Ordering::Greater=>high=middle,Ordering::Equal=>return Ok(Some(ids[middle]))}}Ok(None)}
pub fn parent_range<B:ReceivingWallet>(rows:&[SqliteRow],indices:&[usize],identity:i64,parent_column:usize,port:&mut Port<'_,'_,'_,B>)->Result<std::ops::Range<usize>>{let(mut low,mut high)=(0,indices.len());while low<high{port.work(1,0)?;let middle=low+(high-low)/2;if integer(&rows[indices[middle]],parent_column)?<identity{low=middle+1}else{high=middle}}let start=low;high=indices.len();while low<high{port.work(1,0)?;let middle=low+(high-low)/2;if integer(&rows[indices[middle]],parent_column)?<=identity{low=middle+1}else{high=middle}}Ok(start..low)}
/// 🧾️ Admits only the original native allocation delta absent from earlier SQL receipts.
pub fn settle(control:&mut SqliteSnapshotControl<'_>,remaining:usize,before:usize,after:usize)->Result<()>{let admitted=remaining.checked_sub(control.allocation_remaining_bytes()).ok_or_else(||error(ValueRefusalKind::InvariantViolated,"SQLite secondary allocation receipt regressed"))?;let actual=after.checked_sub(before).and_then(|actual|actual.checked_sub(admitted)).ok_or_else(||error(ValueRefusalKind::InvariantViolated,"SQLite secondary allocation exceeds original native receipt"))?;control.admit_native_allocation_bytes(actual)}

struct Tokens<'a>{text:&'a str}
impl<'a> Tokens<'a>{
 fn new(text:&'a str)->Self{Self{text}}
 fn next<B:ReceivingWallet>(&mut self,port:&mut Port<'_,'_,'_,B>)->Result<Option<&'a str>>{
  loop{let bytes=self.text.as_bytes();let mut skipped=0;while skipped<bytes.len()&&bytes[skipped].is_ascii_whitespace(){if skipped%256==0{port.work(1,0)?}skipped+=1;}self.text=&self.text[skipped..];let bytes=self.text.as_bytes();if bytes.starts_with(b"--"){let mut end=2;while end<bytes.len()&&bytes[end]!=b'\n'{if end%256==0{port.work(1,0)?}end+=1;}port.work(1,0)?;self.text=&self.text[end..];continue}if bytes.starts_with(b"/*"){let mut end=2;while end+1<bytes.len()&&!bytes[end..].starts_with(b"*/"){if end%256==0{port.work(1,0)?}end+=1;}if end+1>=bytes.len(){return Err(invalid("SQLite authored declaration has an unterminated comment"))}port.work(1,0)?;self.text=&self.text[end+2..];continue}break}
  let Some(first)=self.text.chars().next()else{return Ok(None)};let bytes=self.text.as_bytes();let end=if matches!(bytes[0],b'\''|b'"'|b'`'|b'['){let quote=if bytes[0]==b'['{b']'}else{bytes[0]};let mut end=1;let mut next=256;loop{if end>=bytes.len(){return Err(invalid("SQLite authored declaration has an unterminated quote"))}if end>=next{port.work(1,0)?;next+=256}if bytes[end]==quote{end+=1;if quote!=b']'&&end<bytes.len()&&bytes[end]==quote{end+=1;continue}break end}end+=1;}}else if bytes[0].is_ascii_alphanumeric()||bytes[0]==b'_'||bytes[0]>=128{let mut end=0;while end<bytes.len()&&(bytes[end].is_ascii_alphanumeric()||bytes[end]==b'_'||bytes[end]>=128){if end%256==0{port.work(1,0)?}end+=1;}end}else{first.len_utf8()};let token=&self.text[..end];self.text=&self.text[end..];Ok(Some(token))
 }
}
fn identifier_matches<B:ReceivingWallet>(name:&str,token:&str,port:&mut Port<'_,'_,'_,B>)->Result<bool>{
 let bytes=token.as_bytes();let quoted=bytes.first().is_some_and(|first|matches!(*first,b'"'|b'`'|b'['));let(payload,quote,escaped)=if quoted{let quote=if bytes[0]==b'['{b']'}else{bytes[0]};if bytes.len()<2||bytes[bytes.len()-1]!=quote{return Err(invalid("SQLite authored identifier quote is invalid"))}(&bytes[1..bytes.len()-1],quote,quote!=b']')}else{(bytes,0,false)};if payload.is_empty(){return Err(invalid("SQLite authored table name is empty"))}let(mut at,mut original)=(0usize,0usize);while at<payload.len(){if original%256==0{port.work(1,0)?}let byte=payload[at];if name.as_bytes().get(original).is_none_or(|candidate|!candidate.eq_ignore_ascii_case(&byte)){return Ok(false)}at+=1;if escaped&&byte==quote{if payload.get(at)!=Some(&quote){return Err(invalid("SQLite authored identifier escape is invalid"))}at+=1;}original+=1;}Ok(original==name.len())
}
/// 📜️ Compares bounded borrowed SQL tokens, preserving exact bytes of quoted literals.
fn same_token<B:ReceivingWallet>(left:&str,right:&str,port:&mut Port<'_,'_,'_,B>)->Result<bool>{if left.len()!=right.len(){return Ok(false)}let exact=left.starts_with(['\'','"'])||right.starts_with(['\'','"']);for(left,right)in left.as_bytes().chunks(256).zip(right.as_bytes().chunks(256)){port.work(1,0)?;let matches=if exact{left==right}else{left.eq_ignore_ascii_case(right)};if !matches{return Ok(false)}}Ok(true)}
/// 📜️ Validates borrowed authored declarations with bounded scanning and comparison work.
pub fn validate_declaration<B:ReceivingWallet>(source:&str,authored:&str,port:&mut Port<'_,'_,'_,B>)->Result<()>{let mut source=Tokens::new(source);let mut authored=Tokens::new(authored);loop{port.work(1,0)?;match(source.next(port)?,authored.next(port)?){(None,None)=>return Ok(()),(Some(a),Some(b))=>{if !same_token(a,b,port)?{return Err(invalid("SQLite declaration differs from the authored receiving schema"))}},(Some(";"),None)if source.next(port)?.is_none()=>return Ok(()),(None,Some(";"))if authored.next(port)?.is_none()=>return Ok(()),_=>return Err(invalid("SQLite declaration differs from the authored receiving schema"))}}}

/// 📏️ Checks borrowed database extents using original paid work and literal refusals.
pub fn check_database<B:ReceivingWallet>(database:&SqliteDatabase,port:&mut Port<'_,'_,'_,B>)->Result<()>{
 let limits=port.control.limits();if database.tables.len()>limits.max_tables{return Err(error(ValueRefusalKind::WorkLimit,"SQLite original table census exceeds its ceiling"))}let(mut rows,mut values,mut schema,mut scalars)=(0usize,0usize,0usize,0usize);
 for table in &database.tables{port.work(1,0)?;schema=schema.checked_add(table.sql.len()).and_then(|bytes|bytes.checked_add(table.name.len())).ok_or_else(||error(ValueRefusalKind::OwnershipLimit,"SQLite original schema extent overflow"))?;if schema>limits.max_schema_bytes{return Err(error(ValueRefusalKind::OwnershipLimit,"SQLite original schema exceeds its ceiling"))}for row in &table.rows{port.work(2,0)?;rows=rows.checked_add(1).ok_or_else(||error(ValueRefusalKind::WorkLimit,"SQLite original row census overflow"))?;if rows>limits.max_rows||row.values.len()>limits.max_columns{return Err(error(ValueRefusalKind::WorkLimit,"SQLite original row or column census exceeds its ceiling"))}for value in &row.values{port.work(3,0)?;let bytes=match value{SqliteValue::Null=>0,SqliteValue::Integer(_)|SqliteValue::Real(_)=>8,SqliteValue::Text(text)=>text.len(),SqliteValue::Blob(bytes)=>bytes.len()};values=values.checked_add(bytes).ok_or_else(||error(ValueRefusalKind::OwnershipLimit,"SQLite original value extent overflow"))?;if matches!(value,SqliteValue::Integer(_)|SqliteValue::Real(_)){scalars=scalars.checked_add(bytes).ok_or_else(||error(ValueRefusalKind::OwnershipLimit,"SQLite original scalar extent overflow"))?}if values>limits.max_value_bytes{return Err(error(ValueRefusalKind::OwnershipLimit,"SQLite original values exceed their ceiling"))}}}}
 if port.phase()==SqliteSnapshotPhase::ReconstructSnapshot{port.control.admit_reconstruction_scalar_bytes(scalars)?}Ok(())
}

/// 🧬️ Borrows one domain's authored table declaration and declared column extent.
pub struct AuthoredTable<'a>{pub name:&'a str,pub declaration:&'a str,pub columns:usize}
/// 🛂️ Validates borrowed table metadata without creating an unowned parsed schema.
pub fn validate_schema<B:ReceivingWallet>(database:&SqliteDatabase,authored:&[AuthoredTable<'_>],port:&mut Port<'_,'_,'_,B>)->Result<()>{if database.tables.len()!=authored.len(){return Err(invalid("SQLite snapshot requires its authored table census"))}let limits=port.control.limits();if limits.max_tables<authored.len(){return Err(error(ValueRefusalKind::OwnershipLimit,"SQLite authored table census exceeds original ceiling"))}let mut bytes=0usize;for specification in authored{let table=database.tables.iter().find(|table|table.name.eq_ignore_ascii_case(specification.name)).ok_or_else(||invalid("SQLite authored table is missing"))?;bytes=bytes.checked_add(table.sql.len()).and_then(|bytes|bytes.checked_add(table.name.len())).ok_or_else(||error(ValueRefusalKind::OwnershipLimit,"SQLite schema byte extent overflow"))?;if bytes>limits.max_schema_bytes||limits.max_columns<specification.columns{return Err(error(ValueRefusalKind::OwnershipLimit,"SQLite authored declaration exceeds original schema ceiling"))}validate_declaration(&table.sql,specification.declaration,port)?;}Ok(())}

/// 📑️ Checks the original authored schema through borrowed declaration tokens and paid work.
pub fn validate_schema_sql<B:ReceivingWallet>(database:&SqliteDatabase,sql:&str,port:&mut Port<'_,'_,'_,B>)->Result<()>{
 let limits=port.control.limits();if sql.len()>limits.max_schema_bytes||database.tables.len()>limits.max_tables{return Err(error(ValueRefusalKind::OwnershipLimit,"SQLite authored schema exceeds original ceiling"))}
 let mut tokens=Tokens::new(sql);let mut count=0usize;let mut schema_bytes=0usize;
 loop{
  let original=tokens.text;let Some(create)=tokens.next(port)?else{break};if !create.eq_ignore_ascii_case("CREATE")||tokens.next(port)?.is_none_or(|token|!token.eq_ignore_ascii_case("TABLE")){return Err(invalid("SQLite authored schema requires CREATE TABLE declarations"))}
  let name=tokens.next(port)?.ok_or_else(||invalid("SQLite authored table name is missing"))?;
  let mut found=None;for table in &database.tables{port.work(1,0)?;if identifier_matches(&table.name,name,port)?{found=Some(table);break}}let table=found.ok_or_else(||invalid("SQLite authored table is missing"))?;
  let mut depth=0usize;let mut columns=0usize;let mut first=None;let mut ended=false;while let Some(token)=tokens.next(port)?{if depth==1&&first.is_none()&&!matches!(token,"("|")"|","){first=Some(token)}if depth==1&&matches!(token,")"|","){if first.is_some_and(|word:&str|!["CONSTRAINT","PRIMARY","FOREIGN","CHECK"].iter().any(|keyword|word.eq_ignore_ascii_case(keyword))){columns=columns.checked_add(1).ok_or_else(||error(ValueRefusalKind::WorkLimit,"SQLite authored column census overflow"))?}first=None;}match token{"("=>depth=depth.checked_add(1).ok_or_else(||error(ValueRefusalKind::DepthLimit,"SQLite authored declaration depth overflow"))?,")"=>depth=depth.checked_sub(1).ok_or_else(||invalid("SQLite authored declaration parentheses are unbalanced"))?,";" if depth==0=>{ended=true;break},_=>{}}}
  if depth!=0{return Err(invalid("SQLite authored declaration parentheses are unbalanced"))}if columns==0||columns>limits.max_columns{return Err(error(ValueRefusalKind::WorkLimit,"SQLite authored column census exceeds original ceiling"))}let consumed=original.len()-tokens.text.len();let declaration=original[..consumed].trim();validate_declaration(&table.sql,declaration,port)?;
  count=count.checked_add(1).ok_or_else(||error(ValueRefusalKind::WorkLimit,"SQLite authored table census overflow"))?;schema_bytes=schema_bytes.checked_add(table.sql.len()).and_then(|bytes|bytes.checked_add(table.name.len())).ok_or_else(||error(ValueRefusalKind::OwnershipLimit,"SQLite authored schema extent overflow"))?;if schema_bytes>limits.max_schema_bytes{return Err(error(ValueRefusalKind::OwnershipLimit,"SQLite authored schema exceeds original ceiling"))}if !ended{break}
 }
 if count!=database.tables.len(){return Err(invalid("SQLite snapshot requires its authored table census"))}
 for(index,table)in database.tables.iter().enumerate(){let mut declarations=Tokens::new(sql);let mut depth=0usize;let mut names=0usize;while let Some(token)=declarations.next(port)?{if depth==0&&token.eq_ignore_ascii_case("CREATE"){declarations.next(port)?;let token=declarations.next(port)?.ok_or_else(||invalid("SQLite authored table name is missing"))?;if identifier_matches(&table.name,token,port)?{names=names.checked_add(1).ok_or_else(||error(ValueRefusalKind::WorkLimit,"SQLite authored identity census overflow"))?}}else{match token{"("=>depth+=1,")"=>depth=depth.saturating_sub(1),_=>{}}}}if names!=1{return Err(invalid("SQLite authored table identity must occur exactly once"))}for previous in &database.tables[..index]{port.work(1,0)?;if same_token(&table.name,&previous.name,port)?{return Err(invalid("SQLite authored table identity is duplicated"))}}}Ok(())
}

